"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { cn } from "./kgcraft-utils";

type StyledProps<T extends React.ElementType> = Omit<
  React.ComponentProps<T>,
  "className"
> & { className?: string };

function Tabs({ className, ...props }: StyledProps<typeof TabsPrimitive.Root>) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      className={cn(
        "group/tabs flex min-w-0 flex-col gap-2 data-[orientation=vertical]:flex-row",
        className,
      )}
      {...props}
    />
  );
}

function TabsList({
  className,
  variant = "default",
  ...props
}: StyledProps<typeof TabsPrimitive.List> & { variant?: "default" | "line" }) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(
        "group/tabs-list bg-kgcraft-secondary text-kgcraft-muted-foreground inline-flex w-fit items-center gap-1 rounded-lg p-1 data-[orientation=vertical]:flex-col",
        variant === "line" &&
          "border-kgcraft-border rounded-none border-b bg-transparent p-0",
        className,
      )}
      {...props}
    />
  );
}

function TabsTrigger({
  className,
  ...props
}: StyledProps<typeof TabsPrimitive.Tab>) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={cn(
        "text-kgcraft-muted-foreground hover:text-kgcraft-foreground focus-visible:ring-kgcraft-ring data-[active]:bg-kgcraft-background data-[active]:text-kgcraft-foreground group-data-[variant=line]/tabs-list:data-[active]:border-b-foreground inline-flex items-center justify-center gap-2 rounded-md border border-transparent px-3 py-1.5 text-sm font-medium whitespace-nowrap transition-colors outline-none group-data-[variant=line]/tabs-list:rounded-none group-data-[variant=line]/tabs-list:border-b-2 focus-visible:ring-2 focus-visible:ring-offset-2 data-[active]:shadow-sm group-data-[variant=line]/tabs-list:data-[active]:bg-transparent group-data-[variant=line]/tabs-list:data-[active]:shadow-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({
  className,
  ...props
}: StyledProps<typeof TabsPrimitive.Panel>) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={cn(
        "focus-visible:ring-kgcraft-ring min-w-0 flex-1 outline-none focus-visible:ring-2",
        className,
      )}
      {...props}
    />
  );
}

export { Tabs, TabsList, TabsTrigger, TabsContent };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Generated KGCraft UI theme. Override --kgcraft-* to customize. */
@theme inline {
  --color-kgcraft-background: var(--kgcraft-background);
  --color-kgcraft-foreground: var(--kgcraft-foreground);
  --color-kgcraft-primary: var(--kgcraft-primary);
  --color-kgcraft-primary-foreground: var(--kgcraft-primary-foreground);
  --color-kgcraft-secondary: var(--kgcraft-secondary);
  --color-kgcraft-secondary-foreground: var(--kgcraft-secondary-foreground);
  --color-kgcraft-accent: var(--kgcraft-accent);
  --color-kgcraft-accent-foreground: var(--kgcraft-accent-foreground);
  --color-kgcraft-muted-foreground: var(--kgcraft-muted-foreground);
  --color-kgcraft-border: var(--kgcraft-border);
  --color-kgcraft-input: var(--kgcraft-input);
  --color-kgcraft-ring: var(--kgcraft-ring);
  --color-kgcraft-destructive: var(--kgcraft-destructive);
}

:root {
  --kgcraft-background: oklch(1 0 0);
  --kgcraft-foreground: oklch(0.145 0 0);
  --kgcraft-primary: oklch(0.852 0.199 91.936);
  --kgcraft-primary-foreground: oklch(0.421 0.095 57.708);
  --kgcraft-secondary: oklch(0.967 0.001 286.375);
  --kgcraft-secondary-foreground: oklch(0.21 0.006 285.885);
  --kgcraft-accent: oklch(0.97 0 0);
  --kgcraft-accent-foreground: oklch(0.205 0 0);
  --kgcraft-muted-foreground: oklch(0.556 0 0);
  --kgcraft-border: oklch(0.922 0 0);
  --kgcraft-input: oklch(0.922 0 0);
  --kgcraft-ring: oklch(0.708 0 0);
  --kgcraft-destructive: oklch(0.577 0.245 27.325);
}

.dark {
  --kgcraft-background: oklch(0.145 0 0);
  --kgcraft-foreground: oklch(0.985 0 0);
  --kgcraft-primary: oklch(0.795 0.184 86.047);
  --kgcraft-primary-foreground: oklch(0.421 0.095 57.708);
  --kgcraft-secondary: oklch(0.274 0.006 286.033);
  --kgcraft-secondary-foreground: oklch(0.985 0 0);
  --kgcraft-accent: oklch(0.269 0 0);
  --kgcraft-accent-foreground: oklch(0.985 0 0);
  --kgcraft-muted-foreground: oklch(0.708 0 0);
  --kgcraft-border: oklch(1 0 0 / 10%);
  --kgcraft-input: oklch(1 0 0 / 15%);
  --kgcraft-ring: oklch(0.556 0 0);
  --kgcraft-destructive: oklch(0.704 0.191 22.216);
}
